D.LocalClientValues[32126]="战歌氏族依靠震慑和威吓来战胜敌人，他们的氏族名就得名于他们可怕的战吼和行军过程中雷鸣般的战鼓声。这些骇人的战鼓由塔布羊皮蒙在疑似食人魔头骨的骨架上制成，以纪念氏族脱离食人魔帝国，获得自由的历史。"
