D.LocalClientValues[32539]="作为成年仪式的一部分，每个霜狼兽人都要杀死一头霜鬃野猪并将他们的族谱尽可能完整地刻在野猪最大的獠牙上。家族历史和传统对霜狼氏族非常重要，所以每一季他们都会猎取最大的霜鬃野猪，以记载氏族的谱系。"
