D.LocalClientValues[32551]="食人魔社会中的首个重大技术创新就是摒弃了用手拿着石头砸人的方法，改为将石头绑在一根非常长的棍子顶端，并用它来击打敌人。这项创新在食人魔社会中引发了巨大的分歧，最终以这个早已被遗忘的部族分裂为战槌和石拳两个氏族而告终。"
