D.LocalClientValues[32674]="蛛魔是远古时代亚基虫族的后裔。经历过与巨魔的无数次战争之后，大约半数亚基虫族迁移到遥远的北方，在诺森德地下建立起宏伟而怪诞的巨型城市——传说中的艾卓-尼鲁布。而巫妖王的到来对凶残的蛛魔一族来说无异于一个巨大的灾难。经过和天灾军团的长期战争，许多这种蛛形怪物都投向了天灾军团，残存的反抗者则被驱赶到更深的地下，躲藏了起来。"
