D.LocalClientValues[32689]="这是用贵重金属制做成的一对雕像的残余部分。在它们上面，看不到丝毫雕凿或浇筑的痕迹，仿佛它们根本不是出自任何工匠之手。两个雕像表现的都是暗夜精灵。其中牧师是男性，德鲁伊是女性。它们一定有着某种特殊的代表意义。"
