D.LocalClientValues[33295]="尽管大部分食人魔生来就有两只眼睛，但每一代中总有一小撮食人魔会出现返祖现象，生来就只有一只眼睛。大部分氏族都认为这些食人魔拥有超凡的力量，注定会成为大人物。有一个倒霉的独眼食人魔法师在一次决斗中丢失了自己的眼睛，于是就将这块拳头大的石头代替它塞入眼眶，结果却发现它有着魔法属性。"
