D.LocalClientValues[33798]="弓背是用一块岩石般坚硬的木材刻成的，几乎没法拉开。这把弓是从一开始就这么坚硬，还是因为随着时光的流逝石化了？考古学家们一直争论不休。无论如何，它的尺寸与重量都表明，只有最富有经验的牛头人猎人才能够使用它。"
