D.LocalClientValues[33800]="尽管有许多凹痕和擦痕，你还是可以分辨出这把曾经风光无限的锤子上蚀刻着黑石氏族的印记。黑石氏族是第一个掌握黑石熔炼技术的兽人氏族。这种矿石正是以他们的氏族名称命名的。因此，黑石兽人偏好在战斗中使用钝头武器，以纪念他们的祖先。"
