D.LocalClientValues[33820]="这颗保存完好的眼球一度曾属于血环氏族的某位酋长。当氏族的统治者行将就木时，历代酋长都必须完成一个萨满仪式，通过挖出自己眼球的方式来预见未来的死亡。你可以想象到这颗浑浊不清的眼球在被挖出时所见证到的可怕命运。"
