D.LocalClientValues[33936]="在这片不为人知的潘达利亚大陆上，住着一个名叫熊猫人的神秘种族。可敬的熊猫人喜欢与友同乐，畅享美食，自得其乐地避世隐居，也正因为如此，他们的文化才得以繁荣发展，免受外部世界的影响。尽管熊猫人天生爱好和平，但却有着充满动乱与纷争的历史。"
