D.LocalClientValues[34088]="食人魔喜欢炫耀自己魁梧的体格，因此他们会尽量避免让衣物遮盖太多的皮肤。为了让自己在敌人眼中更加可怕，他们喜欢用这些研磨工具制作彩绘来装扮自己。这套研钵与研杵呈黄色，表明它曾属于石拳氏族。"
