D.LocalClientValues[34105]="托维尔本是泰坦们创造的岩石生物。他们被创造出来的目的是守卫奥丹姆的秘密。他们拥有猫一样的头部和下半身，以及人类的上半身。如同诸多泰坦造物一样，托维尔受到了血肉诅咒。现存的托维尔分为三个部族——拉穆卡恒、奥西斯（这个部族几乎已经彻底灭绝）和尼斐塞特。为了能恢复他们的岩石身躯，尼斐塞特和死亡之翼结成了同盟。"
