D.LocalClientValues[34499]="这个美丽的护身符上用闪亮的黄金制造出许多环形和棱角花纹，中间环绕着一颗泪滴形的硕大翡翠。在这块翡翠深处，你能看见一个发光的小球体，包裹着一张模糊的暗夜精灵面孔。发光球体似乎一直在翡翠内部不停地移动，却又不像被困住的飞虫那样来回乱窜。"
