D.LocalClientValues[34761]="在德莱尼到来之前，这块石碑的碎片已经在塔拉多躺了几百年。上面记载了食人魔皇室发布的捣毁数个兽人定居点的命令，以报复一些叛军突袭高里亚奴隶贸易车队的行为。这些命令应该得到了执行，因为那些城镇已经不复存在了，只有这块石碑静静诉说着那段黑暗的历史。"
