D.LocalClientValues[35212]="已知最早的巨魔来自于赞达拉部族，这个部族也是所有其他巨魔的起源。随着历史的推演，赞达拉巨魔成为超越于一切巨魔之上的牧师阶层，致力于记录和保存巨魔的社会和文化传统。在赞达拉分裂出来的许多部族中，最具权威的是古拉巴什和阿曼尼。"
