D.LocalClientValues[35966]="牛头人一直以来都在努力保护自然的平衡，并时刻遵循着他们所信仰的女神：大地母亲的意愿。众多游牧部族聚集在同一面大旗下，定居于莫高雷的肥沃平原上。要不是兽人及时伸出了援手，这个种族可能已经被劫掠成性的半人马灭绝了。牛头人至今依然牢记这笔血债，为保护自己的土地而与部落并肩作战。"
