D.LocalClientValues[36744]="最高伤害"
D.LocalClientValues[36745]="托尔巴拉德曾经是激流堡王国的领土，但在第二次兽人战争中被肆虐的兽人夷平并抛弃了。多年之后，库尔提拉斯夺回了这座岛屿，一群巫师接管了要塞的废墟，将其改造为一座大型魔法监狱。\\n\\n在这场大规模的战斗中，攻方队伍需要同时占领铁甲兵营、典狱官岗哨和熔渣车间来获得胜利。进攻方还可以使用岛上荒废的攻城载具来摧毁三座塔楼以延长战斗的持续时间。\\n\\n"
