D.LocalClientValues[36885]="高贵的德莱尼人从他们生活着的阿古斯世界逃出来之后，被燃烧军团追杀了数不清的岁月，最终在一个遥远的星球定居。他们与这个世界的原住民——信奉萨满教义的兽人和平相处，并给这里起名为德拉诺。在兽人被燃烧军团腐蚀而变得嗜血好战之后，德莱尼人几乎遭到了灭顶之灾。一部分幸存者逃到了艾泽拉斯，并在这里找到了共同对抗燃烧军团的盟友。"
